function ml_private(){return getenv('TI_MASTER_DIR') ?: ($GLOBALS['private'] ?? dirname(__DIR__,2).'/tradingintel-private');}
function ml_rows($sql,$args=[]){$s=ml_db()->prepare($sql);$s->execute($args);return $s->fetchAll();}
function ml_dt($s){return new DateTimeImmutable($s,new DateTimeZone('UTC'));}
function ml_time($s,$n){return ml_dt($s)->modify('+'.$n.' minutes')->format('Y-m-d\TH:i');}
function ml_uint($q,$k,$default,$max){$v=$q[$k]??$default;if(filter_var($v,FILTER_VALIDATE_INT)===false||$v<0||$v>$max)throw new InvalidArgumentException('Invalid '.$k);return (int)$v;}
function ml_range($q){$m=ml_meta();$a=$q['start']??substr($m['first'],0,10);$b=$q['end']??substr($m['last'],0,10);foreach([$a,$b] as $v){if(!is_string($v)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v)||ml_dt($v)->format('Y-m-d')!==$v)throw new InvalidArgumentException('Dates must be YYYY-MM-DD');}if($a>$b)throw new InvalidArgumentException('Start follows end');return [$a,$b];}
function ml_cursor($q,$ctx,$default){if(empty($q['cursor']))return $default;$d=json_decode(base64_decode(strtr((string)$q['cursor'],'-_','+/'),true)?:'null',true);if(!is_array($d)||count($d)!==3||$d[0]!==$ctx||!is_scalar($d[1])||!is_int($d[2]))throw new InvalidArgumentException('Cursor does not match this query');return [$d[1],$d[2]];}
function ml_next($ctx,$a,$b){return rtrim(strtr(base64_encode(json_encode([$ctx,$a,(int)$b])),'+/','-_'),'=');}
function ml_decode($occ,$raw,$rid){$k=$rid*20;$state=ord($raw[$k]);if($state<2)return ['status'=>$state?'eligible_unfilled':'ineligible'];$at=ord($raw[$k+1]);$px=fn($i)=>unpack('V',substr($raw,$i,4))[1]/4;$price=$px($k+2);$m=ml_meta()['settings'];$r=['status'=>'filled','entry_bar_et'=>ml_time($occ['confirm'],$at),'entry'=>$price];if(isset($occ['entry_context'][$at]))$r['entry_context']=['available_at_et'=>$r['entry_bar_et'],...ec_labels(ord($occ['entry_context'][$at]))];$reasons=['stop','target','window close','ambiguous: stop first','stop gap'];foreach(['buy'=>1,'sell'=>-1] as $name=>$side){$j=$k+($side===1?6:12);$exit=$px($j+2);$r[$name]=['stop'=>$price-$side*$m['stop'],'target'=>$price+$side*$m['tp'],'exit_bar_et'=>ml_time($occ['confirm'],ord($raw[$j])),'exit'=>$exit,'reason'=>$reasons[ord($raw[$j+1])],'net_points'=>$side*($exit-$price)-$m['fee']/$m['point'],'net_usd'=>($side*($exit-$price)*$m['point']-$m['fee'])*$m['qty']];}return $r;}
function ml_raw($r){$s=gzinflate($r['labels'],count(ml_rules())*20);if($s===false||strlen($s)!==count(ml_rules())*20)throw new RuntimeException('Snapshot label record damaged');return $s;}
function ml_rank($q,$a,$b){$m=ml_meta();$min=ml_uint($q,'min_occ',2,10000000);$fills=ml_uint($q,'min_fills',1,10000000);$limit=max(1,ml_uint($q,'limit',25,100));$page=ml_uint($q,'page',0,1000000);$full=$a<=substr($m['first'],0,10)&&$b>=substr($m['last'],0,10);$args=[];$src='totals';
 if(!$full){$src='(SELECT sid,rid,sum(eligible) eligible,sum(n) n,sum(bnet) bnet,sum(bw) bw,sum(bl) bl,sum(snet) snet,sum(sw) sw,sum(sl) sl FROM roll INDEXED BY roll_dates WHERE first_day>=? AND end_day<=? GROUP BY sid,rid)';$args=[$a,$b];}
 $sql="SELECT t.*,s.name AS sequence,u.name AS entry_rule,k.occurrences,k.completed FROM $src t JOIN seq s USING(sid) JOIN rules u USING(rid) JOIN (SELECT sid,count(*) occurrences,sum(CASE WHEN complete=1 AND end_day<=? THEN 1 ELSE 0 END) completed FROM occ WHERE first_day>=? AND confirm<? GROUP BY sid HAVING count(*)>=CAST(? AS INTEGER)) k USING(sid) WHERE t.n>=CAST(? AS INTEGER) ORDER BY max(t.bnet,t.snet) DESC,CASE WHEN t.bnet>t.snet THEN t.bw WHEN t.snet>t.bnet THEN t.sw ELSE max(t.bw,t.sw) END*1.0/max(1,t.n) DESC,t.n DESC,t.sid,t.rid LIMIT ".($limit+1)." OFFSET ".($page*$limit);
 $rows=ml_rows($sql,array_merge($args,[$b,$a,ml_time($b.'T00:00',1440),$min,$fills]));$more=count($rows)>$limit;if($more)array_pop($rows);return ['rows'=>$rows,'next_page'=>$more?$page+1:null];}
function ml_result($q){ml_select_run($q);$res=$q['resource']??'manifest';if(in_array($res,['consistency_manifest','consistency_rankings','consistency_example'],true))return cr_result($q);if($res==='swing_levels')return sv_result($q);if($res==='entry_context_report')return ec_report($q);if($res==='entry_context_details')return ec_details($q);if($res==='historical_context')return hr_context($q);if($res==='historical_report')return hr_report($q);$m=ml_meta();if($res==='manifest')return ['snapshot'=>$m,'rules'=>array_values(ml_rules()),'timezone'=>'America/New_York wall time, offsets not supplied','timestamp_convention'=>'Candle timestamps identify bar opens; signals available only at confirmation close','resources'=>['manifest','candles','rankings','examples','curve','fill_levels','historical_context','historical_report','entry_context_report','entry_context_details','swing_levels','consistency_manifest','consistency_rankings','consistency_example']];
 [$a,$b]=ml_range($q);$end=ml_time($b.'T00:00',1440);if($res==='rankings')return ml_rank($q,$a,$b);if($res==='fill_levels')return fl_rank($q,$a,$b);$sid=ml_uint($q,'sid',0,10000000);$rid=isset($q['rid'])?ml_uint($q,'rid',0,count(ml_rules())-1):null;$ctx=substr(hash('sha256',json_encode([$m['snapshot_id']??$m['engine_sha256'],$res,$a,$b,$sid,$rid,fl_filters($q)])),0,20);
 if($res==='candles'){$limit=max(1,ml_uint($q,'limit',1000,5000));[$ts,$id]=ml_cursor($q,$ctx,['',0]);$rows=ml_rows('SELECT * FROM candles WHERE ts>=? AND ts<? AND (ts,id)>(?,CAST(? AS INTEGER)) ORDER BY ts,id LIMIT '.($limit+1),[$a,$end,$ts,$id]);$more=count($rows)>$limit;if($more)array_pop($rows);$last=end($rows);return ['candles'=>$rows,'next_cursor'=>$more?ml_next($ctx,$last['ts'],$last['id']):null];}
 if(!in_array($res,['examples','curve'],true))throw new InvalidArgumentException('Unknown resource');if($res==='curve'&&($rid===null||(!$sid&&!isset(ml_rules()[$rid]['spec']['sourceCandle']))))throw new InvalidArgumentException('Specify sid and rid');
 $where='first_day>=? AND confirm<?'.($sid?' AND o.sid=?':'');$args=[$a,$end];if($sid)$args[]=$sid;[$extra,$extraArgs]=fl_where($q,$rid);$where.=$extra;$args=array_merge($args,$extraArgs);
 if($res==='curve'){$s=ml_db()->prepare("SELECT o.* FROM occ o WHERE $where AND complete=1 AND end_day<=? ORDER BY id");$s->execute([...$args,$b]);$exits=['buy'=>[],'sell'=>[]];$n=0;while($o=$s->fetch()){$v=ml_decode($o,ml_raw($o),$rid);if($v['status']!=='filled')continue;$n++;foreach(['buy','sell'] as $side){$t=$v[$side];$e=$t['exit_bar_et'];$exits[$side][$e]=($exits[$side][$e]??0)+$t['net_usd'];}}
 $daily=[];$dd=[];foreach($exits as $side=>$values){ksort($values);$eq=$peak=$draw=0;foreach($values as $stamp=>$net){$eq+=$net;$peak=max($eq,$peak);$draw=max($draw,$peak-$eq);$daily[substr($stamp,0,10)][$side]=$eq;}$dd[$side]=$draw;}ksort($daily);$last=['buy'=>0,'sell'=>0];$points=[];foreach($daily as $date=>$v){$last=array_merge($last,$v);$points[]=['date'=>$date,...$last];}return ['fills'=>$n,'drawdown_usd'=>$dd,'daily_equity'=>$points];}
 $limit=max(1,ml_uint($q,'limit',100,500));[$id,$slot]=ml_cursor($q,$ctx,[1,0]);$rs=ml_rules();$out=[];$s=ml_db()->prepare("SELECT o.*,s.name FROM occ o JOIN seq s USING(sid) WHERE $where AND o.id>=? ORDER BY o.id LIMIT ".($limit+1));$s->execute([...$args,$id]);
 while($o=$s->fetch()){$done=$o['complete']&&$o['end_day']<=$b;$raw=$done?ml_raw($o):null;foreach($rs as $k=>$u){if(($rid!==null&&$k!==$rid)||($o['id']==$id&&$k<$slot))continue;if(count($out)===$limit)return ['examples'=>$out,'next_cursor'=>ml_next($ctx,(int)$o['id'],$k)];$out[]=['occurrence_id'=>(int)$o['id'],'sequence_id'=>(int)$o['sid'],'rule_id'=>$k,'features'=>['available_at_et'=>ml_time($o['confirm'],1),'sequence'=>$o['name'],'legs'=>json_decode($o['features'],true),'entry_rule'=>$u['spec'],'level_reference'=>fl_reference(json_decode($o['features'],true),$u['spec'])],'outcome'=>!$done?['status'=>'incomplete_window']:ml_decode($o,$raw,$k)];}}
 return ['examples'=>$out,'next_cursor'=>null];}

